css:
.stack {
  display: grid;
  gap: 16px;
  max-width: 320px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
}

.row {
  padding: 10px 14px;
  border-bottom: 1px solid #e4e4e7;
}

.row:last-child {
  border-bottom: none;
}

.drop {
  padding: 32px 16px;
  border: 2px dashed #f97316;
  border-radius: 8px;
  color: #9a3412;
  text-align: center;
}
